import { mayExport } from './policy.js';

export type Role = 'viewer' | 'analyst' | 'admin';

export function downloadReportCsv(role: Role, reportId: string): { status: number; body: string } {
  if (!mayExport(role)) return { status: 403, body: 'forbidden' };
  return { status: 200, body: `report_id\n${reportId}\n` };
}

export function mayExport(role: 'viewer' | 'analyst' | 'admin'): boolean {
  return role === 'analyst' || role === 'admin';
}

import { strict as assert } from 'node:assert';
import { downloadReportCsv } from '../src/export-controller.js';

assert.equal(downloadReportCsv('viewer', 'r-1').status, 403);
assert.equal(downloadReportCsv('analyst', 'r-1').status, 200);
